func newStoredMileage() unsafe.Pointer { return unsafe.Pointer(new(storedmileage.StoredMileage)) }

func newNStoredMileage(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]storedmileage.StoredMileage, n)))
}

func ptrStoredMileage(p unsafe.Pointer, c int32) any {
	r := (*storedmileage.StoredMileage)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return &r.Status
	case 4:
		return &r.OriginKey
	case 5:
		return &r.DestinationKey
	case 6:
		return &r.IntermediateKeys
	case 7:
		return &r.RouteSignature
	case 8:
		return &r.RouteHash
	case 9:
		return &r.Distance
	case 10:
		return &r.DistanceUnits
	case 11:
		return &r.Provider
	case 12:
		return &r.Source
	case 13:
		return &r.RoutingType
	case 14:
		return &r.Method
	case 15:
		return &r.LocationGranularity
	case 16:
		return &r.DataVersion
	case 17:
		return (*string)(unsafe.Pointer(&r.DistanceProfileID))
	case 18:
		return &r.DistanceProfileName
	case 19:
		return &r.Hazmat
	case 20:
		return &r.HazmatTypes
	case 21:
		return &r.HazmatSignature
	case 22:
		return &r.ProviderMetadata
	case 23:
		return &r.JurisdictionDistances
	case 24:
		return &r.HitCount
	case 25:
		return &r.LastUsedAt
	case 26:
		return &r.LastCalculatedAt
	case 27:
		return &r.Version
	case 28:
		return &r.CreatedAt
	case 29:
		return &r.UpdatedAt
	}
	return nil
}

func valueStoredMileage(p unsafe.Pointer, c int32) any {
	r := (*storedmileage.StoredMileage)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return r.Status
	case 4:
		return r.OriginKey
	case 5:
		return r.DestinationKey
	case 6:
		if r.IntermediateKeys == nil {
			return nil
		}
		return r.IntermediateKeys
	case 7:
		return r.RouteSignature
	case 8:
		return r.RouteHash
	case 9:
		return r.Distance
	case 10:
		return r.DistanceUnits
	case 11:
		return r.Provider
	case 12:
		return r.Source
	case 13:
		return r.RoutingType
	case 14:
		return r.Method
	case 15:
		return r.LocationGranularity
	case 16:
		return r.DataVersion
	case 17:
		return string(r.DistanceProfileID)
	case 18:
		if r.DistanceProfileName == "" {
			return nil
		}
		return r.DistanceProfileName
	case 19:
		return r.Hazmat
	case 20:
		if r.HazmatTypes == nil {
			return nil
		}
		return r.HazmatTypes
	case 21:
		return r.HazmatSignature
	case 22:
		if r.ProviderMetadata == nil {
			return nil
		}
		return r.ProviderMetadata
	case 23:
		if r.JurisdictionDistances == nil {
			return nil
		}
		return r.JurisdictionDistances
	case 24:
		return r.HitCount
	case 25:
		if r.LastUsedAt == nil {
			return nil
		}
		return *r.LastUsedAt
	case 26:
		return r.LastCalculatedAt
	case 27:
		return r.Version
	case 28:
		return r.CreatedAt
	case 29:
		return r.UpdatedAt
	}
	return nil
}
